```python
import threading
import time
from collections import defaultdict
from datetime import datetime, timedelta
from queue import Queue

class ResourceMonitor:
    def __init__(self, max_age_seconds=10):
        self.cpu_metrics = defaultdict(dict)
        self.lock = threading.Lock()
        self.max_age_seconds = max_age_seconds
        self.queue = Queue()
        self.thread = threading.Thread(target=self._process_queue, daemon=True)
        self.thread.start()

    def add_metric(self, agent_id, metric):
        self.queue.put((agent_id, metric))

    def get_metrics(self):
        with self.lock:
            return dict(self.cpu_metrics)

    def _process_queue(self):
        while True:
            agent_id, metric = self.queue.get()
            with self.lock:
                self.cpu_metrics[agent_id][datetime.now()] = metric
                self._expire_old_metrics()

    def _expire_old_metrics(self):
        now = datetime.now()
        for agent_id in list(self.cpu_metrics.keys()):
            for timestamp in list(self.cpu_metrics[agent_id].keys()):
                if now - timestamp > timedelta(seconds=self.max_age_seconds):
                    del self.cpu_metrics[agent_id][timestamp]
            if not self.cpu_metrics[agent_id]:
                del self.cpu_metrics[agent_id]
