Yes, you can use a custom controller to dynamically adjust both CPU and memory limits based on current resource usage. Below is an example of how you can implement such a custom controller in Go. This controller will monitor the resource usage of pods and adjust their CPU and memory limits accordingly.

### Step 1: Set Up the Custom Controller

First, you need to set up a custom controller that watches the resource usage of pods and updates their limits dynamically.

#### Example Custom Controller in Go

```go
package main

import (
	"context"
	"fmt"
	"time"

	v1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/watch"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	"k8s.io/client-go/tools/cache"
	"k8s.io/client-go/util/retry"
)

func main() {
	config, err := rest.InClusterConfig()
	if err != nil {
		panic(err)
	}
	clientset, err := kubernetes.NewForConfig(config)
	if err != nil {
		panic(err)
	}

	queue := make(chan string, 100)
	stopCh := make(chan struct{})

	go watchPods(clientset, queue, stopCh)

	for {
		select {
		case key := <-queue:
			namespace, name, err := cache.SplitMetaNamespaceKey(key)
			if err != nil {
				fmt.Printf("Invalid resource key: %s\n", key)
				continue
			}
			pod, err := clientset.CoreV1().Pods(namespace).Get(context.TODO(), name, metav1.GetOptions{})
			if err != nil {
				fmt.Printf("Error getting pod %s/%s: %v\n", namespace, name, err)
				continue
			}
			updatePodLimits(clientset, pod)
		case <-stopCh:
			return
		}
	}
}

func watchPods(clientset *kubernetes.Clientset, queue chan string, stopCh chan struct{}) {
	watcher, err := clientset.CoreV1().Pods("").Watch(context.TODO(), metav1.ListOptions{})
	if err != nil {
		panic(err)
	}
	defer watcher.Stop()

	for event := range watcher.ResultChan() {
		switch event.Type {
		case watch.Added, watch.Modified:
			key, err := cache.MetaNamespaceKeyFunc(event.Object)
			if err == nil {
				queue <- key
			}
		}
	}
}

func updatePodLimits(clientset *kubernetes.Clientset, pod *v1.Pod) {
	newPod := pod.DeepCopy()

	for i, container := range newPod.Spec.Containers {
		cpuUsage := pod.Status.ContainerStatuses[i].Usage.Cpu().MilliValue()
		memUsage := pod.Status.ContainerStatuses[i].Usage.Memory().Value()

		if cpuUsage > 500 {
			newPod.Spec.Containers[i].Resources.Limits[v1.ResourceCPU] = resource.MustParse("1000m")
		} else {
			newPod.Spec.Containers[i].Resources.Limits[v1.ResourceCPU] = resource.MustParse("500m")
		}

		if memUsage > 128*1024*1024 {
			newPod.Spec.Containers[i].Resources.Limits[v1.ResourceMemory] = resource.MustParse("256Mi")
		} else {
			newPod.Spec.Containers[i].Resources.Limits[v1.ResourceMemory] = resource.MustParse("128Mi")
		}
	}

	retry.OnError(retry.DefaultBackoff, func(err error) bool {
		return true
	}, func() error {
		_, err := clientset.CoreV1().Pods(pod.Namespace).Update(context.TODO(), newPod, metav1.UpdateOptions{})
		return err
	})
}
```

### Step 2: Deploy the Custom Controller

Deploy the custom controller as a Kubernetes pod. You can use a `Deployment` to ensure the controller is always running.

#### Deployment YAML

```yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: resource-controller
spec:
  replicas: 1
  selector:
    matchLabels:
      app: resource-controller
  template:
    metadata:
      labels:
        app: resource-controller
    spec:
      containers:
      - name: resource-controller
        image: your-custom-controller-image
        command: ["your-custom-controller-binary"]
        resources:
          requests:
            cpu: "100m"
            memory: "128Mi"
          limits:
            cpu: "200m"
            memory: "256Mi"
```

### Step 3: Monitor and Adjust

Continuously monitor the resource usage and adjust the thresholds and logic in your custom controller as needed.

### Conclusion

By implementing a custom controller in Go, you can dynamically adjust both CPU and memory limits based on current resource usage. This approach helps optimize resource allocation and improve the overall performance and reliability of your Kubernetes cluster. Make sure to test and validate the logic thoroughly in a staging environment before deploying it to production.

